1	import React, { type CSSProperties } from 'react';
2	import { Button as ChakraButton, IconButton, chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
5	
6	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
7	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
8	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
9	
10	type ZimmButtonBaseProps = {
11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12	  label: string;
13	  type?: 'button' | 'submit' | 'reset';
14	  disabled?: boolean;
15	  /**
16	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
17	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
18	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
19	   * suppressed here rather than by the DOM. Prefer this over `disabled` for
20	   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
21	   *
22	   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
23	   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
24	   */
25	  ariaDisabled?: boolean;
26	  inverse?: boolean;
27	  onClick?: () => void;
28	  style?: CSSProperties;
29	  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
30	  sx?: SystemStyleObject;
31	  /**
32	   * Accessible name, when it has to differ from the visible `label`. Defaults to `label`.
33	   * For a control whose visible text is only meaningful with context — e.g. a size filter
34	   * chip reading "0" that should announce "Add filter: 0" — pass the full phrase here and
35	   * keep `label` as the short visible text.
36	   */
37	  ariaLabel?: string;
38	};
39	
40	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
41	  variant?: 'primary' | 'secondary' | 'social';
42	  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
43	   *  (same responsive size as the social variant, applied to primary/secondary colours). */
44	  size?: 'large' | 'medium' | 'adaptive';
45	  fullWidth?: boolean;
46	  /** Links an explanatory message element by id so screen readers announce it on focus. */
47	  ariaDescribedBy?: string;
48	  /** Optional icon rendered before the label. Pass a ZimmIcon or any React node. */
49	  iconLeading?: React.ReactNode;
50	  /** Optional icon rendered after the label. Pass a ZimmIcon or any React node. */
51	  iconTrailing?: React.ReactNode;
52	} & ({ role?: never; ariaChecked?: never } | { role: 'checkbox' | 'radio'; ariaChecked: boolean }); // `aria-checked` is a selectable control that never exposes what it is set to. // union so the role and its state cannot be supplied apart: a `role="checkbox"` with no // button and never conveys whether it is currently applied. Modelled as a discriminated // — e.g. a filter chip. Without these a screen reader announces the control as a plain // Toggle semantics, for a button that represents a *selectable state* rather than an action
53	
54	type ZimmIconButtonProps = ZimmButtonBaseProps & {
55	  variant: 'icon';
56	  icon: ZimmIconType;
57	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
58	  size?: ZimmIconSize;
59	};
60	
61	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
62	
63	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
64	
65	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
66	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
67	 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
68	 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
69	export const ZimmButton = (props: ZimmButtonProps) => {
70	  const {
71	    label,
72	    type = 'button',
73	    disabled = false,
74	    ariaDisabled = false,
75	    inverse = false,
76	    onClick,
77	    style,
78	    sx,
79	    ariaLabel,
80	  } = props;
81	  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
82	  const handleClick = ariaDisabled ? undefined : onClick;
83	  const ariaDisabledAttr = ariaDisabled || undefined;
84	  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
85	
86	  if (props.variant === 'icon') {
87	    return (
88	      <IconButton
89	        aria-label={ariaLabel ?? label}
90	        type={ariaDisabled ? 'button' : type}
91	        isDisabled={disabled}
92	        aria-disabled={ariaDisabledAttr}
93	        onClick={handleClick}
94	        variant={inverse ? 'iconInverse' : 'icon'}
95	        size="icon"
96	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
97	        style={style}
98	        sx={sx}
99	      />
100	    );
101	  }
102	
103	  const variant = props.variant ?? 'primary';
104	  // social → 'social' Chakra size; adaptive → reuses the same 'social' size entry (same
105	  // responsive height/padding tokens, different variant colours); large → 'lg'; medium → 'sm'.
106	  const size = variant === 'social' || props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
107	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
108	  // inverse has no effect on the social variant (no socialInverse exists in the theme).
109	  const chakraVariant = variant === 'social' ? 'social' : `${variant}${inverse ? 'Inverse' : ''}`;
110	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
111	  // The props type pairs these two, so no runtime guard is needed to keep aria-checked off a
112	  // plain action button.
113	  const role = 'role' in props ? props.role : undefined;
114	  const ariaChecked = 'ariaChecked' in props ? props.ariaChecked : undefined;
115	
116	  return (
117	    <ChakraButton
118	      type={ariaDisabled ? 'button' : type}
119	      isDisabled={disabled}
120	      aria-disabled={ariaDisabledAttr}
121	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
122	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
123	      aria-label={ariaLabel ?? label}
124	      aria-describedby={ariaDescribedBy}
125	      role={role}
126	      aria-checked={ariaChecked}
127	      onClick={handleClick}
128	      variant={chakraVariant}
129	      size={size}
130	      width={props.fullWidth ? '100%' : undefined}
131	      style={style}
132	      sx={sx}
133	    >
134	      {props.iconLeading && (
135	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
136	          {props.iconLeading}
137	        </chakra.span>
138	      )}
139	      <chakra.span __css={labelStyle}>{label}</chakra.span>
140	      {props.iconTrailing && (
141	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
142	          {props.iconTrailing}
143	        </chakra.span>
144	      )}
145	    </ChakraButton>
146	  );
147	};
