1	import { useLayoutEffect, useState } from 'react';
2	
3	export type PendingRefinements = Record<string, string[]>;
4	
5	type UseFilterDrawerStateParams = {
6	  /** Whether the filter drawer is currently open — pending state resyncs from the
7	   *  currently-applied filters every time this transitions to true. */
8	  isOpen: boolean;
9	  /** The category currently applied to the page (from the route), used as the initial
10	   *  pending category selection. */
11	  categoryId?: string;
12	  /** The currently-applied refinements — pass searchParams.refine (the real URL-derived
13	   *  ground truth), NOT productSearchResult.selectedRefinements (the SFCC API field that
14	   *  only reflects what the backend chose to echo back, which is often incomplete).
15	   *  Values may be a pipe-separated string ('Black|White'), an array, or a number. */
16	  selectedRefinements?: Record<string, string | number | (string | number)[] | undefined>;
17	};
18	
19	type UseFilterDrawerStateReturn = {
20	  pendingCategoryId: string | undefined;
21	  setPendingCategoryId: (categoryId: string | undefined) => void;
22	  pendingRefine: PendingRefinements;
23	  setValues: (attributeId: string, values: string[]) => void;
24	  removeValue: (attributeId: string, value: string) => void;
25	  clearAll: () => void;
26	  /** Re-derives pendingRefine from a (possibly different) selectedRefinements snapshot —
27	   *  same parsing the drawer-open resync uses. For a caller that reverts a pending category
28	   *  change back to the currently-applied category (e.g. removing the category chip): that
29	   *  category change already cleared pendingRefine via clearAll, so reverting it must also
30	   *  restore whatever refine is actually still applied, not leave the buffer empty. */
31	  resyncPendingRefine: (selectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => void;
32	};
33	
34	/**
35	 * Parses a searchParams.refine-shaped object into the buffered PendingRefinements shape —
36	 * split out so both the drawer-open resync effect and a caller-triggered resync
37	 * (resyncPendingRefine) share one implementation.
38	 */
39	const parseSelectedRefinements = (
40	  selectedRefinements: UseFilterDrawerStateParams['selectedRefinements'],
41	): PendingRefinements => {
42	  const initial: PendingRefinements = {};
43	  Object.entries(selectedRefinements ?? {}).forEach(([attributeId, rawValue]) => {
44	    if (attributeId === 'cgid' || rawValue == null) return;
45	    // searchParams.refine values can be arrays (from buildAppliedRefine), pipe-separated
46	    // strings ('Black|White' — SFCC URL encoding), or plain numbers. Handle all three so
47	    // the resync works correctly regardless of whether the value was round-tripped through
48	    // the URL parser or set directly.
49	    const values: string[] = Array.isArray(rawValue) ? rawValue.map(String) : String(rawValue).split('|');
50	    if (values.length > 0 && values[0] !== '') initial[attributeId] = values;
51	  });
52	  return initial;
53	};
54	
55	/**
56	 * Buffers SFCC-847 filter-drawer selections (category + every refinement facet) in local
57	 * state instead of applying each click straight to the URL/product grid. Resyncs from the
58	 * page's currently-applied filters every time the drawer opens, so a value chosen and then
59	 * abandoned (drawer closed without pressing APPLY) never reaches the URL, and reopening
60	 * after a previous APPLY reflects reality rather than stale local state.
61	 *
62	 * @returns pending category/refinement selections plus mutators. The caller is responsible
63	 * for actually applying them (navigating) when the shopper presses APPLY.
64	 */
65	export const useFilterDrawerState = ({
66	  isOpen,
67	  categoryId,
68	  selectedRefinements,
69	}: UseFilterDrawerStateParams): UseFilterDrawerStateReturn => {
70	  const [pendingCategoryId, setPendingCategoryId] = useState<string | undefined>(categoryId);
71	  const [pendingRefine, setPendingRefine] = useState<PendingRefinements>({});
72	
73	  // useLayoutEffect (not useEffect) — runs synchronously after DOM commit and before the
74	  // browser paints. This prevents the visible flash of stale checkbox state that useEffect
75	  // causes: with useEffect the drawer renders once with the previous pendingRefine (user
76	  // briefly sees wrong checked state), then the effect fires and corrects it. The filter
77	  // drawer is always closed during SSR so the isOpen guard means this body never runs
78	  // server-side — the layout-effect SSR warning does not apply here.
79	  useLayoutEffect(() => {
80	    if (!isOpen) return;
81	    setPendingRefine(parseSelectedRefinements(selectedRefinements));
82	    setPendingCategoryId(categoryId);
83	    // Resync is keyed on `isOpen` alone. `categoryId`/`selectedRefinements` change on every
84	    // navigation — including the one APPLY itself triggers — so including them here would
85	    // re-run this effect right after APPLY and stomp the just-applied selection straight
86	    // back to whatever the next render resolves it to.
87	  }, [isOpen]);
88	
89	  const resyncPendingRefine = (nextSelectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => {
90	    setPendingRefine(parseSelectedRefinements(nextSelectedRefinements));
91	  };
92	
93	  const setValues = (attributeId: string, values: string[]) => {
94	    setPendingRefine((prev) => {
95	      if (values.length === 0) {
96	        const { [attributeId]: _removed, ...rest } = prev;
97	        return rest;
98	      }
99	      return { ...prev, [attributeId]: values };
100	    });
101	  };
102	
103	  const removeValue = (attributeId: string, value: string) => {
104	    setPendingRefine((prev) => {
105	      const next = (prev[attributeId] ?? []).filter((v) => v !== value);
106	      if (next.length === 0) {
107	        const { [attributeId]: _removed, ...rest } = prev;
108	        return rest;
109	      }
110	      return { ...prev, [attributeId]: next };
111	    });
112	  };
113	
114	  const clearAll = () => setPendingRefine({});
115	
116	  return {
117	    pendingCategoryId,
118	    setPendingCategoryId,
119	    pendingRefine,
120	    setValues,
121	    removeValue,
122	    clearAll,
123	    resyncPendingRefine,
124	  };
125	};
126	
127	export type AppliedRefine = Record<string, string | number | (string | number)[]>;
128	
129	/**
130	 * Merges buffered facet selections into the page's real `searchParams.refine` object —
131	 * the pure computation behind the drawer's APPLY handler, split out so it's testable
132	 * without a component or navigation. Every attribute this drawer manages (every non-cgid
133	 * attributeId SFCC currently returns as a refinement) is fully overwritten from
134	 * `pendingRefine` — including being deleted if the shopper unticked it back to empty —
135	 * while any attribute this drawer does not manage (e.g. StoreInventoryFilter's `ilids`) is
136	 * left exactly as it was in `currentRefine`.
137	 *
138	 * @returns a new refine object; never mutates `currentRefine`.
139	 */
140	export const buildAppliedRefine = (
141	  currentRefine: AppliedRefine,
142	  managedAttributeIds: string[],
143	  pendingRefine: PendingRefinements,
144	): AppliedRefine => {
145	  const nextRefine: AppliedRefine = { ...currentRefine };
146	  managedAttributeIds.forEach((attributeId) => {
147	    delete nextRefine[attributeId];
148	  });
149	  Object.entries(pendingRefine).forEach(([attributeId, values]) => {
150	    nextRefine[attributeId] = values;
151	  });
152	  return nextRefine;
153	};
